const norm = (s) =>
  String(s || "").normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9]/g, "");

/** Resolve a circuit outline by any of the given keys (name, city, country). */
export function getCircuit(...keys) {
  for (const key of keys) {
    if (!key) continue;
    const rec = CIRCUITS[norm(key)];
    if (rec) return rec;
  }
  return null;
}
